import { EventEmitter } from 'events';
import { promisify } from 'util';
import * as crypto from 'crypto';

interface MetricEvent {
  timestamp: number;
  source: string;
  level: string;
  payload: Record<string, unknown>;
}

class FormatEngine {
  private templates: Map<string, string> = new Map();
  private sanitizers: Map<string, (v: string) => string> = new Map();

  constructor() {
    this.sanitizers.set('default', (v) => v.replace(/[%$`]/g, ''));
    this.sanitizers.set('metric', (v) => v.replace(/[^a-zA-Z0-9_.\-]/g, '_'));
    this.sanitizers.set('passthrough', (v) => v);
  }

  registerTemplate(name: string, template: string): void {
    this.templates.set(name, template);
  }

  getSanitizer(level: string): (v: string) => string {
    if (level === 'TRACE' || level === 'DEBUG') {
      return this.sanitizers.get('passthrough')!;
    }
    return this.sanitizers.get('default')!;
  }

  format(template: string, args: Record<string, unknown>, sanitizer: (v: string) => string): string {
    return template.replace(/\{(\w+)\}/g, (_, key) => {
      const val = args[key];
      if (val === undefined) return `{${key}}`;
      return sanitizer(String(val));
    });
  }
}

class AsyncMetricBuffer {
  private buffer: MetricEvent[] = [];
  private flushPromise: Promise<void> | null = null;
  private readonly maxSize = 100;

  async enqueue(event: MetricEvent): Promise<void> {
    this.buffer.push(event);
    if (this.buffer.length >= this.maxSize) {
      await this.flush();
    }
  }

  async flush(): Promise<MetricEvent[]> {
    if (this.flushPromise) await this.flushPromise;
    const batch = [...this.buffer];
    this.buffer = [];
    return batch;
  }
}

class MonitoringAgent extends EventEmitter {
  private formatEngine: FormatEngine;
  private metricBuffer: AsyncMetricBuffer;
  private outputHandlers: Map<string, (msg: string) => void> = new Map();
  private contextStack: Map<string, string> = new Map();

  constructor() {
    super();
    this.formatEngine = new FormatEngine();
    this.metricBuffer = new AsyncMetricBuffer();
    this.setupDefaultHandlers();
    this.formatEngine.registerTemplate('standard', '[{timestamp}] [{level}] {source}: {message}');
    this.formatEngine.registerTemplate('metric', 'METRIC {name}={value} source={source}');
  }

  private setupDefaultHandlers(): void {
    this.outputHandlers.set('console', (msg) => {
      process.stdout.write(msg + '\n');
    });
    this.outputHandlers.set('syslog', (msg) => {
      // Simulated syslog via sprintf-style formatting
      const formatted = this.syslogFormat(msg);
      process.stderr.write(formatted + '\n');
    });
  }

  private syslogFormat(msg: string): string {
    // Internal formatting that uses printf-style specifiers
    // This is the downstream consumer that interprets format specifiers
    const facility = 1;
    const severity = 6;
    const pri = facility * 8 + severity;
    return `<${pri}>${msg}`;
  }

  setContext(key: string, value: string): void {
    this.contextStack.set(key, value);
  }

  async log(level: string, source: string, message: string, meta?: Record<string, unknown>): Promise<void> {
    const event: MetricEvent = {
      timestamp: Date.now(),
      source,
      level,
      payload: { message, ...meta }
    };

    await this.metricBuffer.enqueue(event);

    const sanitizer = this.formatEngine.getSanitizer(level);
    const args = {
      timestamp: new Date(event.timestamp).toISOString(),
      level,
      source: sanitizer(source),
      message: sanitizer(message),
      ...Object.fromEntries(
        Object.entries(meta || {}).map(([k, v]) => [k, sanitizer(String(v))])
      )
    };

    const template = '[{timestamp}] [{level}] {source}: {message}';
    const formatted = this.formatEngine.format(template, args, sanitizer);

    for (const [name, handler] of this.outputHandlers) {
      handler(formatted);
    }

    this.emit('logged', event);
  }

  async reportMetric(name: string, value: number, tags?: Record<string, string>): Promise<void> {
    const sanitizer = this.formatEngine.getSanitizer('METRIC');
    const args = {
      name: sanitizer(name),
      value: String(value),
      source: this.contextStack.get('service') || 'unknown',
      ...tags
    };

    const template = 'METRIC {name}={value} source={source}';
    const formatted = this.formatEngine.format(template, args, sanitizer);

    for (const [, handler] of this.outputHandlers) {
      handler(formatted);
    }
  }

  async processExternalEvent(rawEvent: string): Promise<void> {
    let parsed: { level?: string; source?: string; message?: string; meta?: Record<string, unknown> };
    try {
      parsed = JSON.parse(rawEvent);
    } catch {
      await this.log('ERROR', 'agent', 'Failed to parse external event');
      return;
    }

    const level = parsed.level || 'INFO';
    const source = parsed.source || 'external';
    const message = parsed.message || '';

    // Route through standard logging pipeline
    await this.log(level, source, message, parsed.meta);
  }

  async shutdown(): Promise<void> {
    const remaining = await this.metricBuffer.flush();
    if (remaining.length > 0) {
      process.stdout.write(`Flushed ${remaining.length} remaining events\n`);
    }
  }
}

// Application entry point
async function main() {
  const agent = new MonitoringAgent();
  agent.setContext('service', 'payment-gateway');

  // Simulate receiving external events (e.g., from HTTP endpoint)
  const externalPayload = process.argv[2] || '{"level":"INFO","source":"test","message":"hello"}';
  await agent.processExternalEvent(externalPayload);

  await agent.reportMetric('requests.total', 42, { env: 'prod' });
  await agent.shutdown();
}

main().catch(console.error);
